-- 00 — PRÉVIA em produção (SOMENTE LEITURA). Esperado: 36 migrações (o 02 confere nome+hash e recusa se não); a 0037 ausente;
-- nenhuma concessão com as 4 ações novas; as concessões do MOVA exatamente nas versões/ações abaixo (o 04 recusa se mudarem).
select (select count(*) from financeiro_v2.fv2_migracao) migracoes,
       (select count(*) from financeiro_v2.fv2_migracao where nome = '0037_operacoes_de_conta_a_pagar.sql') tem_0037,
       (select count(*) from financeiro_v2.fv2_concessao where acoes ?| array['financeiro_v2.reclassificar_conta_a_pagar', 'financeiro_v2.ajustar_conta_a_pagar', 'financeiro_v2.mover_competencia_conta_a_pagar', 'financeiro_v2.cancelar_conta_a_pagar']) concessoes_com_as_acoes,
       (select count(*) from pg_proc where proname in ('fv2_pode_estreita', 'fv2_periodo_estreito', 'fv2_compra_elegivel', 'fv2_colunas_alteradas', 'fv2_forma_estreita_da_conta', 'fv2_lancamento_operacao_estreita', 'fv2_ajuste_estreito_confere', 'fv2_conta_estreita_coerente', 'fv2_ajuste_estreito')) funcoes_novas_presentes;
select organizacao_id, unidade_id, versao, situacao, acoes,
       (acoes @> '["financeiro_v2.baixar_por_comprovante","financeiro_v2.corrigir_conta_a_pagar","financeiro_v2.enviar_documento","financeiro_v2.registrar_conta_parcelada","financeiro_v2.registrar_emprestimo","financeiro_v2.registrar_intercompany","financeiro_v2.registrar_juros","financeiro_v2.registrar_obrigacao","financeiro_v2.ver"]'::jsonb and '["financeiro_v2.baixar_por_comprovante","financeiro_v2.corrigir_conta_a_pagar","financeiro_v2.enviar_documento","financeiro_v2.registrar_conta_parcelada","financeiro_v2.registrar_emprestimo","financeiro_v2.registrar_intercompany","financeiro_v2.registrar_juros","financeiro_v2.registrar_obrigacao","financeiro_v2.ver"]'::jsonb @> acoes) acoes_conferem
  from financeiro_v2.fv2_concessao where usuario_id = '839a6da8-649d-4b6f-81c7-cb51c5c919cd' order by organizacao_id, unidade_id;
